INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-21' FROM countries WHERE name_en = 'Sweden';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'Fully decentralised — no domestic B2B mandate', 'This deep-dive page reflects publicly available technical guidance as of July 2026 and is provided for general awareness, not legal or tax advice. Sweden''s domestic B2B mandate question remains genuinely open pending the national inquiry due November 2027 — confirm current developments directly with DIGG or Skatteverket before making long-term compliance decisions.', 'Sweden has one of Europe''s longest e-invoicing track records in the public sector — and one of its more open questions about whether that ever extends to private business.', 'Sweden has never operated a single mandated national schema the way Norway (EHF) or Denmark (OIOUBL) do — it went straight to the European standard.', 'There is genuinely no central Swedish platform — this is one of the purest decentralised models in this tracker. Sweden has no legislated domestic B2B mandate. What''s genuinely new: a national inquiry into ViDA implementation launched 5 February 2026, explicitly tasked with assessing whether to mandate domestic B2B/G2B e-invoicing, with findings due no later than 30 November 2027.', 'With no domestic B2B mandate, "getting ready" here means positioning sensibly rather than meeting a hard deadline.', 'No penalty framework exists for B2B because no mandate exists yet — the real story here is what the 2026 inquiry might produce.' FROM countries WHERE name_en = 'Sweden';
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Sweden';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '2008', 'First partial B2G mandate');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Sweden';
