INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', 'Nov 2027', 'National ViDA inquiry due');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Sweden';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Current formats', '[["Preferred", "Peppol BIS Billing 3.0 (UBL, EN 16931)"], ["Legacy, still accepted", "Svefaktura 1.0 / 2.0"], ["Legacy, being phased out", "SFTI ESAP 6 Fulltextfaktura, EDIFACT"]]', 'Many Swedish businesses still use Svefaktura for B2B trading — if you''re integrating with Swedish partners, be ready to support both Peppol BIS and the older national formats for a while yet.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Sweden';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Signature & archiving', '[["Digital signature", "Not required"], ["Retention period", "7 years"]]', 'No electronic signature requirement applies to either public- or private-sector invoices — a genuinely lighter-touch requirement than Italy''s mandatory XAdES/CAdES.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Sweden';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'No national CIUS beyond Peppol BIS', '[["National extensions", "None beyond the Peppol BIS Billing CIUS itself"]]', 'Unlike Croatia''s HR-FISK or Romania''s RO_CIUS, there''s no additional Swedish-specific layer of mandatory fields to learn — the standard European profile is what applies.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'Sweden';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Standard VAT invoice content', '[["Requirement", "Standard Swedish VAT invoice content rules apply regardless of format"]]', 'Whichever format you use, the underlying legal content requirements for a valid Swedish VAT invoice remain the same — the format question is about structure, not substance.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'Sweden';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'No central platform', '[["Government portal", "None exists"], ["Everything routes via", "The Peppol network"]]', 'Every invoice moves through Peppol Access Points — there''s nothing resembling Croatia''s AMS, Poland''s KSeF, or even Norway''s ELMA as a distinct government-run directory layer.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Sweden';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Governance', '[["DIGG", "Swedish Peppol Authority (currently being merged into PTS)"], ["SFTI", "Standards body — Single Face to Industry — not a transmission platform"], ["Skatteverket", "Tax Agency; a co-sponsor of the B2B mandate assessment"]]', 'DIGG''s ongoing merger with the Post and Telecom Authority (PTS) may shift the day-to-day contact point for Peppol Authority matters — watch for updated guidance during the transition.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Sweden';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Finding a trading partner', '[["Tool", "Peppol Online Directory"], ["What it shows", "Connection status, accepted formats, business identifiers (GLN or VAT number)"]]', 'Use the directory to check whether a specific Swedish counterparty is Peppol-connected and which formats/identifiers it accepts before you build an integration around assumptions.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 3 FROM countries WHERE name_en = 'Sweden';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'B2B today: voluntary but common', '[["Legal requirement", "None"], ["Practical reality", "High adoption, increasingly expected by larger buyers"]]', 'Nothing stops two Swedish businesses from exchanging structured e-invoices today by mutual agreement — many already do, well ahead of any legal requirement to.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Sweden';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🔮 What the inquiry is actually assessing', NULL, NULL, 'Beyond the binary "mandate or not" question, the commissioner is specifically examining whether Skatteverket could use e-invoicing data for VAT administration and fraud prevention — a hint that any eventual mandate could carry a reporting component, not just a format requirement.', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Sweden';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🏛️ DIGG''s merger into PTS', NULL, NULL, 'Watch for how Sweden''s Peppol Authority function is preserved (or restructured) as DIGG merges with the Post and Telecom Authority — this is an institutional change worth tracking separately from the policy question.', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Sweden';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🇪🇺 The only firm deadline: ViDA itself', NULL, NULL, 'Regardless of what the domestic inquiry concludes, Sweden still faces the EU-wide ViDA cross-border e-invoicing requirement from 1 July 2030 — cross-border-trading Swedish businesses should prepare for that date independently of the domestic question.', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 3 FROM countries WHERE name_en = 'Sweden';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📈 High voluntary adoption as a hedge', NULL, NULL, 'Because B2B Peppol/Svefaktura adoption is already widespread, a future mandate — if legislated — would likely formalise existing practice for many businesses rather than force a from-scratch build, similar to how Norway''s 2027 mandate largely does today.', NULL, NULL);
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Sweden';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'If you supply Swedish public bodies, confirm Peppol BIS Billing 3.0 capability', 'Connect via a certified Access Point or approved e-invoicing service provider — this remains firmly mandatory for the public sector.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Sweden';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Check the Peppol Online Directory before building integrations', 'Confirm your Swedish counterparty''s connection status and which formats/identifiers they accept — don''t assume Peppol BIS 3.0 universally, given legacy format persistence.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Sweden';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Migrate off Svefaktura and SFTI ESAP 6 where practical', 'These formats are being actively discouraged, even though still technically accepted — moving to Peppol BIS 3.0 now avoids a scramble later.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Sweden';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'For B2B, there''s nothing to register for — just monitor the inquiry', 'Track the national ViDA implementation inquiry, due by 30 November 2027, since its findings will determine whether and how a domestic mandate emerges.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Sweden';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Set up standard 7-year archiving', 'Ensure your e-invoice records meet the retention period regardless of which format you''re using.');
